export function isInternationalBuild(): boolean {
    return queryStringParams.locale !== undefined && queryStringParams.locale !== 'en-gb';
}

export const delay = (ms: number) => new Promise<void>(
    (resolve) => setTimeout(resolve, ms)
);

export const eventDispatched = (eventEmitter: EventEmitter, eventName: string) => new Promise<void>(
    (resolve) => eventEmitter.once(eventName, resolve)
);

export const nextFrame = () => new Promise<void>(
    (resolve) => requestAnimationFrame(() => resolve())
);

/**
 * a delay function that uses gsap, this runs closer in sync to spine animations than the original delay function
 * @param ms how long you want to wait
 * @returns a promise that resolves after the set time
 */
export const gsapDelay = (ms: number) => new Promise<void>(
    (resolve) => gsap.delayedCall(ms / 1000, resolve)
);

/**
 * a delay function that uses the pixi ticker, use this to keep in time with anything using the pixi ticker e.g generic-reels
 * using other delay functions can cause drift as there is a minfps limit that caps the delta value
 * @param ms how long you want to wait
 * @returns a promise that resolves after the set time
 */
export const pixiDelay = (ms: number) => new Promise<number>(
    (resolve) => {
        const ticker: Ticker = Ticker.shared;
        const startTime = ticker.lastTime;
        const endTime = startTime + ms;
        const onTick = () => {
            if (ticker.lastTime >= endTime) {
                cleanUp();
                resolve(ticker.lastTime - endTime);
            }
        };
        const cleanUp = () => ticker.remove(onTick);
        ticker.add(onTick);
    }
);

export function buildDynamicString(text: string, options: ITextOptions): string {
    for (const key of Object.keys(options)) {
        const paramToReplace = new RegExp(`{{${key}}}`, 'g');
        text = text.replace(paramToReplace, options[key].toString());
    }
    return text;
}

export function buildDynamicStringBlock<T>(stringBlock: T, options: { [key: string]: string | number }): T {
    const result = JSON.parse(JSON.stringify(stringBlock), (_, value: unknown) => {
        if (typeof value === 'string') {
            for (const key of Object.keys(options)) {
                const paramToReplace = new RegExp(`{{${key}}}`, 'g');
                value = (value as string).replace(paramToReplace, options[key].toString());
            }
        }
        return value;
    });

    return result;
}

export function shuffleArray<T>(array: T[]): T[] {
    if (array.length <= 1) { return array; }

    for (let currentIndex = array.length - 1; currentIndex >= 0; currentIndex--) {
        const randomIndex: number = Math.floor(Math.random() * (currentIndex + 1));

        [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
    }

    return array;
}

/**
 * Creates a log body from params.
 * @param verbosity Logging level to use.
 * @param logType Type of log: 'exception', 'metric', or 'session'.
 * @param gameName Name of the game this log is for.
 * @param message Optional Custom message.
 * @param eventName Optional event name (for session events).
 * @param sessionId Optional session ID (defaults to -1 for non-session logs).
 * @param clientTypeId Optional client type ID.
 * @returns An object containing an object with the request headers & an object with the request body
 */
export function createBaseLog(
    verbosity: Verbosity, 
    logType: 'exception' | 'metric' | 'session', 
    gameName?: string, 
    message?: string,
    destination?: 'platform' | 'arcade'
): IBaseLog {
    const domain = {
        debug: 'devarc-api',
        dev: 'devarc-api',
        stage: 'stage-api',
        live: 'api'
    }[environment];

    const headers = {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-Tombola-DeviceIdentifier': device.deviceID,
        'X-Tombola-DeviceType': 'MobileApp'
    };

    let appendString: string = 'web';

    if (device.type.isAndroidNative) {
        appendString = 'android-native';
    } else if (device.type.isIosNative) {
        appendString = 'ios-native';
    }

    let country = queryStringParams.locale.split('-', 1)[0];
    if (country === 'en') { country = 'uk'; }

    const logTypeMap = {
        exception: { tombolaDocType: 'game_client-exception', type: 'log' },
        metric: { tombolaDocType: 'game_client-metric', type: 'metric' },
        session: { tombolaDocType: 'game-studio-client-game-session', type: 'session' }
    };

    const Destination = {
        platform: ['platform'],
        arcade: ['arcade']
    };

    const getDestinations = (dest?: string): string[] => {
        if (!dest || !(dest in Destination)) {
            return ['arcade']; // Default fallback
        }
        return Destination[dest as keyof typeof Destination];
    };

    const body: IBaseLogBody = {
        Verbosity: verbosity,
        Country: country.toUpperCase(),
        Environment: environment.toUpperCase(),
        Department: 'Game',
        Service: 'Arcade game client',
        Game: gameName || queryStringParams.currentSkin || 'Unnamed',
        GameName: gameName || queryStringParams.currentSkin || 'Unnamed',
        EngineName: gameConfig.engineName || '',
        Message: message || `${gameName} Metric Data`,
        Category: 'JavaScript',
        Destinations: getDestinations(destination),
        TombolaDocType: logTypeMap[logType].tombolaDocType,
        Division: 'arcade',
        UserID: userModel.userId,
        Orientation: device.orientation.value,
        Platform: `${device.type.value}-${appendString}`,
        WebGLSupported: device.features.supportsWebGL,
        Value: 0, // Default value so it retains the right type and the index doesn't break
        Type: logTypeMap[logType].type,
        Version: gameConfig.version,
        Timestamp: new Date().toISOString()
    };

    const URL: string = `https://${domain}.tombola.com/logging/v4/log`;

    return { URL, headers, body };
}

export function getLocaleString(): string {
    const region = queryStringParams.locale;
    switch (region) {
        case 'it-it':
            return 'it-IT';
        case 'es-es':
            return 'es-ES';
        case 'se-se':
            return 'sv-SE';
        case 'dk-dk':
            return 'da-DK';
        case 'en-gb':
        default:
            return 'en-GB';
    }
}